package com.bitap.keyboard.core

import java.io.File
import java.security.MessageDigest
import java.time.LocalDateTime
import java.time.format.DateTimeFormatter
import java.util.Locale
import kotlin.math.sqrt
import org.junit.Assert.assertTrue
import org.junit.Assume.assumeTrue
import org.junit.Test

/**
 * Pinyin evaluation v3: training-source-independent CC0 acceptance corpus.
 *
 * The corpus is generated by eval/v3/corpus/build_v3_corpus.py from
 * irvin/cc0-sentences zh-TW daily-chat files converted with zhconv. It is
 * validation-only and must never be used for tuning. The test is skipped by
 * default; set PINYIN_V3_ACCEPTANCE=1 for the one-shot acceptance run.
 *
 * Output: build/pinyin-v3-eval-acceptance.txt (aggregate only: no case ids,
 * inputs, expected strings or candidate details).
 */
class PinyinV3EvalTest {

    private data class EvalCase(
        val id: String,
        val category: String,
        val input: String,
        val expected: List<String>,
        val note: String,
        val source: String,
    )

    private data class CaseResult(
        val case: EvalCase,
        val rank: Int,
        val latencyNanos: Long,
        val fullCoverage: Boolean,
        val oracleHit: Boolean,
        val failureReason: String?,
    ) {
        val top1: Boolean get() = rank == 0
        val top5: Boolean get() = rank in 0..4
        val rankCost: Int get() = if (rank in 0..4) rank + 1 else MISS_RANK_COST
    }

    private val categoryOrder = listOf("natural_short", "natural_medium", "natural_long")
    private val categoryLabels = mapOf(
        "natural_short" to "自然短句",
        "natural_medium" to "自然中句",
        "natural_long" to "自然长句",
    )

    @Test
    fun evaluateV3Acceptance() {
        assumeTrue(
            "v3 acceptance runs only when PINYIN_V3_ACCEPTANCE=1 (one-shot independent validation)",
            System.getenv("PINYIN_V3_ACCEPTANCE") == "1",
        )
        val root = findRepoRoot()
        val dictionaryFile = File(root, "app/src/main/assets/pinyin_dict.tsv")
        val corpusFile = File(root, "eval/v3/corpus/pinyin_cases_v3_validation.tsv")
        assumeTrue("v3 corpus not found: " + corpusFile.absolutePath, corpusFile.isFile)
        assumeTrue("dictionary not found: " + dictionaryFile.absolutePath, dictionaryFile.isFile)
        val cases = loadCases(corpusFile)
        assertTrue("v3 corpus needs >=500 cases but was " + cases.size, cases.size >= 500)
        assertTrue("duplicate case ids", cases.map { it.id }.toSet().size == cases.size)
        assertTrue("duplicate inputs", cases.map { it.input }.toSet().size == cases.size)
        categoryOrder.forEach { category ->
            assertTrue("corpus misses category " + category, cases.any { it.category == category })
        }

        val dictionaryWords = loadDictionaryWords(dictionaryFile)
        val engine = dictionaryFile.useLines { lines -> PinyinEngine.fromLines(lines) }
        assertTrue("engine failed to load dictionary", engine.isReady)
        cases.take(24).forEach { engine.search(it.input, limit = SEARCH_LIMIT) }

        val results = cases.map { runCase(engine, it, dictionaryWords) }
        val report = buildReport(root, corpusFile, engine, results)
        val outputFile = File(root, "build/pinyin-v3-eval-acceptance.txt")
        outputFile.parentFile?.mkdirs()
        outputFile.writeText(report, Charsets.UTF_8)
        println(report)
        println("wrote " + outputFile.absolutePath)
    }

    private fun runCase(engine: PinyinEngine, case: EvalCase, dictionaryWords: Set<String>): CaseResult {
        val started = System.nanoTime()
        val candidates = engine.search(case.input, limit = SEARCH_LIMIT)
        val elapsed = System.nanoTime() - started
        var bestRank = -1
        candidates.forEachIndexed { index, candidate ->
            if (bestRank < 0 && matches(candidate, case)) bestRank = index
        }
        val fullPool = engine.search(case.input, limit = FULL_LIMIT)
        val coverage = requiredCoverage(case.input)
        val fullCoverage = fullPool.any { it.consumedInputLength >= coverage }
        val oracleHit = fullPool.any { matches(it, case) }
        val reason = if (bestRank in 0..4) null else classifyFailure(case, bestRank, candidates.map { it.word }, dictionaryWords)
        return CaseResult(case, bestRank, elapsed, fullCoverage, oracleHit, reason)
    }

    private fun matches(candidate: Candidate, case: EvalCase): Boolean {
        val candidateText = normalizeForMatch(candidate.word)
        if (candidateText.isEmpty()) return false
        val coverage = requiredCoverage(case.input)
        return case.expected.any { alternative ->
            val expectedText = normalizeForMatch(alternative)
            expectedText.isNotEmpty() && candidateText == expectedText && candidate.consumedInputLength >= coverage
        }
    }

    private fun requiredCoverage(input: String): Int = input.count { it.isLetterOrDigit() || it == '\'' }

    private fun classifyFailure(case: EvalCase, bestRank: Int, topCandidates: List<String>, dictionaryWords: Set<String>): String {
        if (bestRank >= 5) return "排序"
        if (topCandidates.isEmpty()) return "切分"
        val alternatives = case.expected.map { normalizeForMatch(it) }.filter { it.isNotEmpty() }
        if (alternatives.any { dictionaryWords.contains(it) }) return "排序"
        val target = alternatives.firstOrNull() ?: return "排序"
        if (!isComposable(target, dictionaryWords)) return "缺词"
        val sameSkeleton = topCandidates.any { candidate ->
            candidate.length == target.length && commonPrefixLength(target, candidate) >= 2
        }
        if (sameSkeleton) return "排序"
        val maxOverlap = topCandidates.maxOfOrNull { candidateOverlap(target, it) } ?: 0.0
        if (maxOverlap >= 0.5) return "切分"
        return "排序"
    }

    private fun buildReport(root: File, corpusFile: File, engine: PinyinEngine, results: List<CaseResult>): String {
        val builder = StringBuilder()
        builder.appendLine("# Bitap pinyin evaluation v3 (CC0 independent acceptance, aggregate only)")
        builder.appendLine("split=validation")
        builder.appendLine("generatedAt=" + LocalDateTime.now().format(DateTimeFormatter.ISO_LOCAL_DATE_TIME))
        builder.appendLine("hostOs=" + System.getProperty("os.name") + " " + System.getProperty("os.version"))
        builder.appendLine("jvm=" + System.getProperty("java.vm.name") + " " + System.getProperty("java.version"))
        builder.appendLine("corpus=" + corpusFile.relativeTo(root).path.replace('\\', '/'))
        builder.appendLine("corpusSha256=" + sha256(corpusFile))
        builder.appendLine("dictionaryEntries=" + engine.entryCount)
        builder.appendLine("searchLimit=" + SEARCH_LIMIT + " oracleLimit=" + FULL_LIMIT)
        builder.appendLine("cases=" + results.size)
        builder.appendLine()
        builder.appendLine("[engineScored]")
        builder.appendLine("n=" + results.size)
        builder.appendLine("top1=" + ratio(results.count { it.top1 }, results.size) + " ci95=" + wilson(results.count { it.top1 }, results.size))
        builder.appendLine("top5=" + ratio(results.count { it.top5 }, results.size) + " ci95=" + wilson(results.count { it.top5 }, results.size))
        builder.appendLine("rankCost.avg=" + averageCost(results) + " total=" + results.sumOf { it.rankCost })
        builder.appendLine("fullCoverage=" + ratio(results.count { it.fullCoverage }, results.size))
        builder.appendLine("oracle=" + ratio(results.count { it.oracleHit }, results.size))
        builder.appendLine("top5ErrorRate=" + percent(results.count { !it.top5 }, results.size) + "%")
        builder.appendLine()
        builder.appendLine("[byCategory]")
        categoryOrder.forEach { category ->
            val categoryResults = results.filter { it.case.category == category }
            if (categoryResults.isEmpty()) return@forEach
            builder.appendLine(
                "  " + category + " (" + (categoryLabels[category] ?: category) + "): " +
                    "n=" + categoryResults.size +
                    " top1=" + ratio(categoryResults.count { it.top1 }, categoryResults.size) +
                    " top5=" + ratio(categoryResults.count { it.top5 }, categoryResults.size) +
                    " rankCost=" + averageCost(categoryResults) +
                    " fullCoverage=" + ratio(categoryResults.count { it.fullCoverage }, categoryResults.size) +
                    " oracle=" + ratio(categoryResults.count { it.oracleHit }, categoryResults.size) +
                    " top1Ci95=" + wilson(categoryResults.count { it.top1 }, categoryResults.size),
            )
        }
        builder.appendLine()
        appendLatency(builder, results)
        builder.appendLine("failureReasons=" + failureReasons(results))
        return builder.toString()
    }

    private fun appendLatency(builder: StringBuilder, results: List<CaseResult>) {
        val values = results.map { it.latencyNanos }.sorted()
        if (values.isEmpty()) {
            builder.appendLine("[latency] n/a")
            return
        }
        fun percentile(percent: Int): Double {
            val index = ((values.size - 1) * percent / 100).coerceIn(0, values.lastIndex)
            return values[index] / 1_000_000.0
        }
        builder.appendLine(
            "[latency] p50=" + formatMillis(percentile(50)) +
                " p95=" + formatMillis(percentile(95)) +
                " p99=" + formatMillis(percentile(99)) +
                " max=" + formatMillis(values.last() / 1_000_000.0),
        )
    }

    private fun failureReasons(results: List<CaseResult>): String {
        val reasons = LinkedHashMap<String, Int>()
        results.filter { !it.top5 }.forEach { result ->
            val reason = result.failureReason ?: "排序"
            reasons[reason] = (reasons[reason] ?: 0) + 1
        }
        return if (reasons.isEmpty()) "none" else reasons.entries.joinToString(" ") { it.key + "=" + it.value }
    }

    private fun loadCases(file: File): List<EvalCase> = file.useLines { lines ->
        lines.mapNotNull { raw ->
            val line = raw.removePrefix("\uFEFF").trimEnd('\r')
            if (line.isBlank() || line.trimStart().startsWith("#")) return@mapNotNull null
            val parts = line.split('\t')
            require(parts.size == 6) { "malformed v3 corpus line: " + line }
            EvalCase(
                id = parts[0].trim(),
                category = parts[1].trim(),
                input = parts[2].trim(),
                expected = parts[3].split('|').map { it.trim() }.filter { it.isNotEmpty() },
                note = parts[4].trim(),
                source = parts[5].trim(),
            )
        }.toList()
    }

    private fun loadDictionaryWords(file: File): Set<String> {
        val words = HashSet<String>()
        file.forEachLine(Charsets.UTF_8) { raw ->
            val line = raw.removePrefix("\uFEFF").trimEnd('\r')
            if (line.isBlank() || line.trimStart().startsWith("#")) return@forEachLine
            val parts = line.split('\t')
            if (parts.size < 2) return@forEachLine
            val word = parts[1].trim()
            if (word.isNotEmpty()) words.add(word)
        }
        return words
    }

    private fun sha256(file: File): String {
        val digest = MessageDigest.getInstance("SHA-256")
        file.inputStream().use { stream ->
            val buffer = ByteArray(1 shl 16)
            while (true) {
                val read = stream.read(buffer)
                if (read < 0) break
                digest.update(buffer, 0, read)
            }
        }
        return digest.digest().joinToString("") { String.format(Locale.ROOT, "%02x", it) }
    }

    private fun findRepoRoot(): File {
        var directory: File? = File(System.getProperty("user.dir") ?: ".").absoluteFile
        while (directory != null) {
            if (File(directory, "eval/v3/corpus/pinyin_cases_v3_validation.tsv").isFile &&
                File(directory, "app/src/main/assets/pinyin_dict.tsv").isFile
            ) {
                return directory
            }
            directory = directory.parentFile
        }
        error("repository root not found from " + System.getProperty("user.dir"))
    }

    private fun isComposable(text: String, words: Set<String>): Boolean {
        var position = 0
        while (position < text.length) {
            var matched = 0
            val maxLength = minOf(10, text.length - position)
            for (length in maxLength downTo 1) {
                if (words.contains(text.substring(position, position + length))) {
                    matched = length
                    break
                }
            }
            if (matched == 0) return false
            position += matched
        }
        return true
    }

    private fun commonPrefixLength(left: String, right: String): Int {
        var index = 0
        while (index < left.length && index < right.length && left[index] == right[index]) index++
        return index
    }

    private fun candidateOverlap(expected: String, candidate: String): Double {
        if (expected.isEmpty() || candidate.isEmpty()) return 0.0
        val remaining = HashMap<Char, Int>()
        expected.forEach { remaining[it] = (remaining[it] ?: 0) + 1 }
        var common = 0
        candidate.forEach { char ->
            val count = remaining[char] ?: 0
            if (count > 0) {
                common++
                remaining[char] = count - 1
            }
        }
        return common.toDouble() / expected.length
    }

    private fun normalizeForMatch(text: String): String =
        text.filter { it.isLetterOrDigit() || isCjk(it) }

    private fun isCjk(char: Char): Boolean =
        char.code in 0x3400..0x4DBF || char.code in 0x4E00..0x9FFF || char.code in 0xF900..0xFAFF

    private fun averageCost(results: List<CaseResult>): String =
        if (results.isEmpty()) "0.00" else String.format(Locale.ROOT, "%.2f", results.sumOf { it.rankCost }.toDouble() / results.size)

    private fun ratio(value: Int, total: Int): String =
        value.toString() + "/" + total + "(" + percent(value, total) + "%)"

    private fun percent(value: Int, total: Int): String =
        if (total == 0) "0.0" else String.format(Locale.ROOT, "%.1f", value * 100.0 / total)

    private fun wilson(hit: Int, total: Int): String {
        if (total == 0) return "n/a"
        val p = hit.toDouble() / total
        val z = 1.96
        val z2 = z * z
        val denominator = 1.0 + z2 / total
        val center = (p + z2 / (2.0 * total)) / denominator
        val half = z * sqrt(p * (1.0 - p) / total + z2 / (4.0 * total * total)) / denominator
        return String.format(
            Locale.ROOT,
            "%.1f%% [%.1f%%, %.1f%%]",
            p * 100.0,
            ((center - half) * 100.0).coerceIn(0.0, 100.0),
            ((center + half) * 100.0).coerceIn(0.0, 100.0),
        )
    }

    private fun formatMillis(value: Double): String = String.format(Locale.ROOT, "%.3f", value)

    companion object {
        private const val SEARCH_LIMIT = 8
        private const val FULL_LIMIT = 64
        private const val MISS_RANK_COST = 9
    }
}
